mapper.select:
select a.id, a.application_no, a.employee_id, e.name as employee_name, e.department as employee_department, a.asset_id, ast.code as asset_code, ast.name as asset_name, a.quantity, a.reason, a.status, a.reject_reason, a.apply_time, a.approve_time, a.approver_id, a.complete_time, a.remark from asset_application a left join employee e on a.employee_id = e.id left join asset ast on a.asset_id = ast.id
and a.application_no like concat('%', #{applicationNo}, '%')
and a.employee_id = #{employeeId}
and a.status = #{status}
order by a.apply_time desc

mapper.update:
update asset_application
application_no = #{applicationNo}, employee_id = #{employeeId}, asset_id = #{assetId}, quantity = #{quantity}, reason = #{reason}, status = #{status}, reject_reason = #{rejectReason}, apply_time = #{applyTime}, approve_time = #{approveTime}, approver_id = #{approverId}, complete_time = #{completeTime}, remark = #{remark}, update_time = #{updateTime}
where id = #{id}
